            VStack(alignment: .leading, spacing: 3) {
                Text(sectionTitle)
                    .font(.system(size: 10, weight: .semibold))
                    .foregroundStyle(Color.secondaryText)
                if model.project.document != nil && model.primaryView == .studio {
                    TextField(
                        "",
